-- Study Abroad country content, BATCH 14: Oman, Jordan, Lebanon, Israel, Iran.
-- Researched from public sources in November 2026 (see backend/TODO_country_tables.md for what still needs checking).
-- Text blocks fill the columns on countries; subject / course rows are linked to subjects / specializations
-- (country_sections.subject_id / specialization_id) so the website links them to those pages.
-- Replaces the earlier '[Sample]' / '[Placeholder]' rows of these 5 countries. Safe to re-run.
-- Requires alembic revision e6a3c9d1f4b7 (alembic upgrade head).
BEGIN;
DELETE FROM country_sections WHERE country_id IN (SELECT id FROM countries WHERE slug IN ('oman', 'jordan', 'lebanon', 'israel', 'iran'));
UPDATE countries SET why_title = 'Why study in Oman?', why_body = '<p>Oman is a stable Gulf country with a growing private higher education sector, strong in engineering, business, health and Arabic studies. Higher education moved under the Ministry of Education after Royal Decree 14/2026.</p><ul><li>English-medium programmes at private universities</li><li>Stable, safe and welcoming country</li><li>Arabic language and culture immersion</li><li>Lower costs than some other Gulf states</li></ul>', visa_title = 'Student visa and residence', visa_body = '<p>The institution usually sponsors a <strong>student residence visa</strong> processed through the Royal Oman Police (ROP). The student collects the residence card at the ROP residency directorate.</p><ul><li>Admission letter from an Omani institution</li><li>Valid passport and medical fitness certificate</li><li>One-year visa, renewable annually while enrolled (guide report)</li><li>Fees reported at about OMR 20-50 for the visa, OMR 20 for the card and OMR 20-50 for the medical test (sources differ)</li><li>Processing reported at between 10 days and 4 weeks</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Royal Oman Police and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Public universities mostly admit Omanis; sources disagree on whether Sultan Qaboos University takes international students, particularly at postgraduate level. Private universities admit internationals directly.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof</li><li>Entrance exam for some programmes</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Private universities set their own fees.</p><ul><li>Private universities: roughly OMR 1,500-6,000+ a year, or from about US$5,000 (guide ranges)</li><li>SQU scholarship for non-Omani students reported as a tuition reduction of up to 20% or a postgraduate waiver (sources differ)</li><li>Living costs: about US$600-$1,000 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with good results</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> IELTS 5.5-6.5 or equivalent; some programmes in Arabic</li></ul>' WHERE slug = 'oman';
UPDATE countries SET why_title = 'Why study in Jordan?', why_body = '<p>Jordan is a stable, hospitable country in the Middle East with well-established universities, strong medicine and engineering programmes and a hub for Arabic-language study.</p><ul><li>Established public and private universities</li><li>Strong in medicine, dentistry, pharmacy and engineering</li><li>Arabic language immersion</li><li>Lower costs than Gulf destinations</li></ul>', visa_title = 'Study residence permit', visa_body = '<p>The university''s international students office normally applies for the <strong>study residence permit</strong> with the Ministry of Interior after you arrive, and it is renewed annually.</p><ul><li>Admission letter and proof of student status</li><li>Passport copy and last entry stamp</li><li>Blood test reported at about JOD 90 in an older university guide</li><li>Nationals of some countries (GCC, Egypt, Syria) are exempt from the permit</li><li>Students on a student visa are reported as not allowed to work (October 2026 portal)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Jordan Ministry of Interior and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university. Jordan adopted a 2026-27 international student admission policy in June 2026, so confirm its details.</p><ul><li>Academic transcripts and certificates, attested</li><li>English or Arabic proficiency</li><li>Entrance exam or minimum grades for medicine and engineering</li><li>Passport copy and photographs</li><li>Application and admission fees</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Fees are charged per credit hour at many universities.</p><ul><li>US$250-$500 per credit hour at Mutah, Yarmouk, Hashemite and JUST (October 2026 portal), plus admission and semester fees</li><li>Guide ranges: Bachelor''s about US$2,000-$6,000 a year, medicine about US$8,000-$15,000 (indicative)</li><li>Living costs: about US$500-$900 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate (Tawjihi equivalent) with good results</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Arabic or English depending on the programme</li></ul>' WHERE slug = 'jordan';
UPDATE countries SET why_title = 'Why study in Lebanon?', why_body = '<p>Lebanon is home to some of the Arab world''s oldest English-medium universities, including the American University of Beirut. The country is facing serious security and economic difficulties, so check advice carefully.</p><ul><li>English-medium AUB, LAU and other universities</li><li>Strong in medicine, engineering and architecture</li><li>Multilingual environment (Arabic, English, French)</li><li>Rich culture and history</li></ul>', visa_title = 'Visa and residence requirements', visa_body = '<p>Students need admission to an accredited Lebanese institution and proof of funds. Students staying beyond their visa need a <strong>one-year student residence permit</strong> from General Security, applied for after arrival.</p><ul><li>Admission letter and proof of sufficient funds</li><li>AUB requires a passport valid for at least 12 months</li><li>Residence permit fee reported at LBP 15,000,000 (AUB, 18 October 2026)</li><li>Some nationalities enter visa-free or on arrival; others need a visa</li><li>Scholarship holders are exempt from the funds requirement</li></ul><p><strong>Safety:</strong> the US State Department lists Lebanon at Level 4 (Do not travel), and UK advice warns against travel to parts of the country. Check your government''s current travel advice before planning to study here.</p><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official General Security Lebanon and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university.</p><ul><li>Academic transcripts and certificates, attested</li><li>English or French proficiency</li><li>Entrance exam (SAT or university test) for some programmes</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>AUB tuition figures were not found in search results; AUB includes health insurance in its 2026-27 student fees.</p><ul><li>Private universities: check each university fee schedule (fees are often charged in US dollars)</li><li>Living costs: highly variable because of the economic situation; confirm locally</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with good results (and SAT where required)</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof for English-medium programmes</li></ul>' WHERE slug = 'lebanon';
UPDATE countries SET why_title = 'Why study in Israel?', why_body = '<p>Israel has research-intensive universities such as the Technion, the Hebrew University and Tel Aviv University, with strengths in technology, science, medicine and entrepreneurship.</p><ul><li>Leading research universities</li><li>Strong tech and start-up ecosystem</li><li>English-taught programmes for international students</li><li>Hebrew language courses</li></ul><p>Check your government''s current travel advice before planning to study here.</p>', visa_title = 'A/2 student visa requirements', visa_body = '<p>International students must hold an <strong>A/2 student visa</strong> issued in their home country through an Israeli diplomatic mission. Hebrew-only language enrolment does not qualify for the visa.</p><ul><li>Admission letter and visa documentation from the university</li><li>Full Israeli health insurance for the stay</li><li>International students may not work in Israel</li><li>Apply well ahead through the Israeli embassy or consulate</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Israeli embassy and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university, often through an international school or office.</p><ul><li>Academic transcripts and certificates</li><li>English (or Hebrew) proficiency</li><li>SAT or entrance exam for some programmes</li><li>Motivation letter and references for graduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition schedules were not found for 2026-27.</p><ul><li>Technion international programme: dormitory rent about NIS 1,270 a month (2025-26 page); check the 2026-27 fact sheet for tuition</li><li>Hebrew University and others: check each university''s current schedule</li><li>Living costs: about US$1,000-$1,800 a month (estimate; Israel is expensive)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with strong results</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof for English-taught programmes</li></ul>' WHERE slug = 'israel';
UPDATE countries SET why_title = 'Why study in Iran?', why_body = '<p>Iran has well-known universities such as the University of Tehran and Sharif University of Technology, with strengths in engineering, medicine and the sciences, and low costs. International students face practical constraints, so check advice carefully.</p><ul><li>Established universities, especially in engineering and medicine</li><li>Low costs</li><li>Persian language and culture study</li><li>Large university system</li></ul><p>Check your government''s current travel advice before planning to study here.</p>', visa_title = 'Student visa requirements', visa_body = '<p>International students need a <strong>student visa (Type E)</strong> issued after university approval. Students typically enter on a one-month visa and report to the university consular office within 5 days.</p><ul><li>Admission and faculty approval with verification of academic qualifications</li><li>Apply for the student residence permit within 30 days of arrival</li><li>Exit visa or university letter needed each time you leave Iran</li><li>International mail and banking disruptions may affect document delivery</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Iranian embassy and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>International applicants apply through the university or the ministry international office.</p><ul><li>Academic transcripts and certificates, attested</li><li>Persian or English proficiency</li><li>Entrance exam or interview for some programmes</li><li>Passport copy and photographs</li><li>Medical certificate</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition and scholarship figures were not found in search results.</p><ul><li>Tuition: check each university international office; fees for international students are set per programme</li><li>Living costs: low, but check local conditions and exchange rates</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with strong results</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Persian or English proof depending on the programme</li></ul>' WHERE slug = 'iran';
COMMIT;
